<?php
declare(strict_types=1);namespace Atlas\Platform\Workflows\Domain;final class Workflow{public function __construct(public readonly string$id,public readonly string$scope,public readonly?string$organizationId,public readonly string$slug,public readonly string$title,public readonly string$summary,public readonly int$version,public readonly?string$sourceResourceVersionId,public readonly array$steps){}public function toArray():array{return['id'=>$this->id,'scope'=>$this->scope,'organization_id'=>$this->organizationId,'slug'=>$this->slug,'title'=>$this->title,'summary'=>$this->summary,'version'=>$this->version,'source_resource_version_id'=>$this->sourceResourceVersionId,'steps'=>array_map(static fn(WorkflowStep$s):array=>$s->toArray(),$this->steps)];}}
